import React, { useEffect, useState, useCallback, useMemo } from "react";
import { v4 as uuidv4 } from 'uuid';
import { Question, Message, DomainStatus, AnswerAttempt } from './types';
import Header from './components/Header';
import ChatPanel from './components/ChatPanel';
import Sidebar from './components/Sidebar';

// New type for fork management
interface Fork {
  id: string;
  parentMessageId: string | null; // Which message this fork branches from
  messages: Message[]; // All messages in this fork
  isActive: boolean; // Whether this fork is currently being viewed
}

const App: React.FC = () => {
  const [forks, setForks] = useState<Fork[]>(() => {
  try {
    const savedForks = localStorage.getItem('chatForks');
    return savedForks ? JSON.parse(savedForks) : [];
  } catch (error) {
    console.error("Failed to parse forks from localStorage", error);
    return [];
  }
});

const [activeForkId, setActiveForkId] = useState<string | null>(() => {
  try {
    const savedActiveForkId = localStorage.getItem('activeForkId');
    return savedActiveForkId ? JSON.parse(savedActiveForkId) : null;
  } catch (error) {
    console.error("Failed to parse activeForkId from localStorage", error);
    return null;
  }
});
  const [questions, setQuestions] = useState<Question[]>([]);
  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
  const [overallScore, setOverallScore] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);

  // Get the currently active fork
  const activeFork = useMemo(() => {
    return forks.find(fork => fork.id === activeForkId) || null;
  }, [forks, activeForkId]);

  // Get visible messages from the active fork
  const visibleMessages = useMemo(() => {
    return activeFork?.messages || [];
  }, [activeFork]);

  // Get current question ID from the last message in active fork
  const currentQuestionId = useMemo(() => {
    if (!visibleMessages.length) return null;
    const lastMessage = visibleMessages[visibleMessages.length - 1];
    return lastMessage?.type === 'question' ? lastMessage.question?.id ?? null : null;
  }, [visibleMessages]);

  // Helper function to create a new fork
  const createFork = useCallback((parentMessageId: string | null = null, initialMessages: Message[] = []): string => {
    const newForkId = uuidv4();
    const newFork: Fork = {
      id: newForkId,
      parentMessageId,
      messages: [...initialMessages],
      isActive: true
    };

    setForks(prevForks => {
      // Deactivate all other forks
      const updatedForks = prevForks.map(fork => ({ ...fork, isActive: false }));
      return [...updatedForks, newFork];
    });

    setActiveForkId(newForkId);
    return newForkId;
  }, []);

  // Helper function to get all messages up to a certain point across all forks
  const getMessagesUpToPoint = useCallback((targetMessageId: string): Message[] => {
    // Find which fork contains the target message
    for (const fork of forks) {
      const messageIndex = fork.messages.findIndex(m => m.id === targetMessageId);
      if (messageIndex !== -1) {
        // Return messages up to and including the target message
        return fork.messages.slice(0, messageIndex + 1);
      }
    }
    return [];
  }, [forks]);

  // Initial data fetching
  useEffect(() => {
    fetch("http://localhost:3001/questions")
      .then(res => {
        if (!res.ok) throw new Error(`Network response was not ok: ${res.statusText}`);
        return res.json();
      })
      .then(data => {
        if (!Array.isArray(data) || data.length === 0) {
          throw new Error("Fetched data is not valid.");
        }
        
        setQuestions(data);
        if (forks.length === 0) { 
          const firstQuestion = data[0];
          const initialMessage: Message = {
            id: "",
            sender: "AI",
            text: "",
            type: "question"
          };
          createFork(null, [initialMessage]); // Yeni sohbeti sadece burada başlat

          const initialDomains: DomainStatus[] = [/*...*/];
          setDomainStatuses(initialDomains);
        }


        // Initialize domain statuses
        const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))]
          .map(name => ({
            name,
            status: name === firstQuestion.domain_name ? 'In Progress' : 'Pending',
            score: 0
          }));
        setDomainStatuses(initialDomains);
      })
      .catch(err => {
        console.error("Error fetching questions:", err);
        const errorMessage: Message = {
          id: uuidv4(),
          sender: 'AI',
          type: 'error',
          text: "Backend'e bağlanılamadı."
        };
        createFork(null, [errorMessage]);
      })
      .finally(() => setIsLoading(false));
  }, [createFork]);

  // Score calculation for visible messages
  const recalculateScores = useCallback((currentVisibleMessages: Message[], allQuestions: Question[]) => {
    if (allQuestions.length === 0) return;

    const domainData: { [key: string]: { score: number; answeredQuestions: Set<number> } } = {};
    const domains = [...new Set(allQuestions.map(q => q.domain_name))];

    domains.forEach(name => {
      domainData[name] = { score: 0, answeredQuestions: new Set() };
    });

    // Only count scores from the visible timeline
    for (const msg of currentVisibleMessages) {
      if (msg.type === 'user_response' && msg.answeredQuestionId && msg.attempts && msg.attempts.length > 0) {
        const question = allQuestions.find(q => q.id === msg.answeredQuestionId);
        if (question) {
          domainData[question.domain_name].answeredQuestions.add(question.id);
        }
      }
    }

    domains.forEach(name => {
      const totalQuestionsInDomain = allQuestions.filter(q => q.domain_name === name).length;
      const questionWeight = 100 / (totalQuestionsInDomain || 1);
      let domainScore = 0;

      currentVisibleMessages
        .filter(m => m.type === 'user_response' && m.answeredQuestionId && domainData[name].answeredQuestions.has(m.answeredQuestionId))
        .forEach(msg => {
          const attempt = msg.attempts?.[0]; // Each message now has only one attempt
          if (attempt) {
            domainScore += (attempt.score / 100) * questionWeight;
          }
        });
      
      domainData[name].score = domainScore;
    });

    const lastQuestionMsg = [...currentVisibleMessages].reverse().find(m => m.type === 'question' && m.question);
    const currentDomainName = lastQuestionMsg?.question?.domain_name;

    const newDomainStatuses: DomainStatus[] = domains.map(name => {
      const data = domainData[name];
      const answeredCount = data.answeredQuestions.size;
      const totalCount = allQuestions.filter(q => q.domain_name === name).length;
      let status: 'Complete' | 'In Progress' | 'Pending' = 'Pending';

      if (answeredCount > 0) {
        status = (answeredCount >= totalCount || name !== currentDomainName) ? 'Complete' : 'In Progress';
      } else if (name === currentDomainName) {
        status = 'In Progress';
      }

      return { name, score: Math.min(100, data.score), status };
    });

    const totalScore = newDomainStatuses.reduce((acc, curr) => acc + curr.score, 0);
    setOverallScore(totalScore / (newDomainStatuses.length || 1));
    setDomainStatuses(newDomainStatuses);
  }, []);

  // Recalculate scores whenever visible messages change
  useEffect(() => {
    recalculateScores(visibleMessages, questions);
  }, [visibleMessages, questions, recalculateScores]);

  // Send message - adds to current fork
  const handleSendMessage = async (prompt: string) => {
    if (!currentQuestionId || isLoading || !activeFork) return;
    setIsLoading(true);

    // Create optimistic message (each message now has only one attempt)
    const optimisticUserMessage: Message = {
      id: uuidv4(),
      sender: 'User',
      type: 'user_response',
      answeredQuestionId: currentQuestionId,
      attempts: [{ 
        text: prompt, 
        score: 0, 
        ai_comment: "...", 
        ai_task: "...", 
        db_answer_id: -1, 
        next_question_id: null 
      }],
      activeAttemptIndex: 0,
      text: ""
    };

    // Add to current fork
    setForks(prevForks => 
      prevForks.map(fork => 
        fork.id === activeForkId 
          ? { ...fork, messages: [...fork.messages, optimisticUserMessage] }
          : fork
      )
    );

    try {
      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, previous_question_id: currentQuestionId })
      });
      
      if (!res.ok) throw new Error(`API error: ${res.statusText}`);
      const apiResponse = await res.json();

      const newAttempt: AnswerAttempt = {
        text: prompt,
        score: apiResponse.score,
        ai_comment: apiResponse.comment,
        ai_task: apiResponse.task,
        db_answer_id: apiResponse.db_answer_id,
        next_question_id: apiResponse.next_question_id,
      };

      setForks(prevForks => 
        prevForks.map(fork => {
          if (fork.id !== activeForkId) return fork;
          
          const updatedMessages = [...fork.messages];
          
          // Update the optimistic message with real data
          const lastMessage = updatedMessages[updatedMessages.length - 1];
          if (lastMessage.type === 'user_response') {
            lastMessage.attempts = [newAttempt];
          }

          // Add next question if needed
          if (apiResponse.next_question_id !== null) {
            const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
            if (nextQuestion) {
              updatedMessages.push({
                id: uuidv4(),
                sender: 'AI',
                type: 'question',
                question: nextQuestion,
                text: ""
              });
            }
          }

          return { ...fork, messages: updatedMessages };
        })
      );

    } catch (err) {
      console.error("Error sending message:", err);
      // Revert optimistic update on error
      setForks(prevForks => 
        prevForks.map(fork => 
          fork.id === activeForkId 
            ? { ...fork, messages: fork.messages.slice(0, -1) }
            : fork
        )
      );
    } finally {
      setIsLoading(false);
    }
  };

  // Edit message - creates a new fork
  const handleEditMessage = async (messageId: string, newText: string) => {
    if (!activeFork) return;
    
    const messageIndex = activeFork.messages.findIndex(m => m.id === messageId);
    if (messageIndex === -1) return;

    const messageToEdit = activeFork.messages[messageIndex];
    if (!messageToEdit.answeredQuestionId || !messageToEdit.attempts) return;

    setIsLoading(true);
    setEditingMessageId(null);

    try {
      const dbAnswerIdToUpdate = messageToEdit.attempts[0]?.db_answer_id;

      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: newText,
          previous_question_id: messageToEdit.answeredQuestionId,
          answer_id_to_edit: dbAnswerIdToUpdate
        }),
      });
      
      if (!res.ok) throw new Error(`API error: ${res.statusText}`);
      const apiResponse = await res.json();

      const newAttempt: AnswerAttempt = {
        text: newText,
        score: apiResponse.score,
        ai_comment: apiResponse.comment,
        ai_task: apiResponse.task,
        db_answer_id: apiResponse.db_answer_id,
        next_question_id: apiResponse.next_question_id,
      };

      // Create new fork with messages up to the edited message
      const messagesUpToEdit = activeFork.messages.slice(0, messageIndex);
      
      // Create new edited message
      const editedMessage: Message = {
        ...messageToEdit,
        id: uuidv4(), // New ID for the edited message
        attempts: [newAttempt],
        activeAttemptIndex: 0
      };

      const newForkMessages = [...messagesUpToEdit, editedMessage];

      // Add next question if needed
      if (apiResponse.next_question_id !== null) {
        const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
        if (nextQuestion) {
          newForkMessages.push({
            id: uuidv4(),
            sender: 'AI',
            type: 'question',
            question: nextQuestion,
            text: ""
          });
        }
      }

      // Create new fork
      createFork(messageId, newForkMessages);

    } catch (err) {
      console.error("Error while editing message:", err);
    } finally {
      setIsLoading(false);
    }
  };

  // Navigate attempt - switches between forks
  const handleNavigateAttempt = (messageId: string, direction: 'prev' | 'next') => {
    // Find all forks that contain different versions of this message
    const relatedForks = forks.filter(fork => 
      fork.messages.some(m => 
        m.answeredQuestionId === visibleMessages.find(vm => vm.id === messageId)?.answeredQuestionId
      )
    );

    if (relatedForks.length <= 1) return;

    // Find current fork index
    const currentForkIndex = relatedForks.findIndex(fork => fork.id === activeForkId);
    if (currentForkIndex === -1) return;

    // Calculate next fork index
    const nextIndex = direction === 'next' 
      ? (currentForkIndex + 1) % relatedForks.length
      : (currentForkIndex - 1 + relatedForks.length) % relatedForks.length;

    // Switch to the next fork
    const nextFork = relatedForks[nextIndex];
    setActiveForkId(nextFork.id);
    
    // Update fork active status
    setForks(prevForks => 
      prevForks.map(fork => ({
        ...fork,
        isActive: fork.id === nextFork.id
      }))
    );
  };

  // Go back to previous question
  const handlePreviousQuestion = () => {
    if (!activeFork || activeFork.messages.length <= 1) return;

    // Find the last user response
    const lastUserResponseIndex = activeFork.messages.length - 1;
    for (let i = activeFork.messages.length - 1; i >= 0; i--) {
      if (activeFork.messages[i].type === 'user_response') {
        // Create new fork with messages up to the previous question
        const previousMessages = activeFork.messages.slice(0, i);
        createFork(activeFork.messages[i].id, previousMessages);
        break;
      }
    }
  };

  return (
    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen flex flex-col">
      <Header 
        onPrevious={handlePreviousQuestion} 
        canGoBack={visibleMessages.some(m => m.type === 'user_response')} 
      />
      <div className="flex flex-1 overflow-hidden min-h-0">
        <ChatPanel
          messages={visibleMessages}
          onSendMessage={handleSendMessage}
          isLoading={isLoading}
          currentQuestionId={currentQuestionId}
          editingMessageId={editingMessageId}
          setEditingMessageId={setEditingMessageId}
          onEditMessage={handleEditMessage}
          onNavigateAttempt={handleNavigateAttempt}
        />
        <Sidebar statuses={domainStatuses} overallScore={overallScore} />
      </div>
    </div>
  );
};

export default App;
